import { beforeEach, describe, expect, it, vi } from "vitest";

const core = vi.hoisted(() => ({
  invoke: vi.fn(),
  isTauri: vi.fn(() => true),
}));

vi.mock("@tauri-apps/api/core", () => core);
vi.mock("@tauri-apps/api/event", () => ({ listen: vi.fn() }));

import { createWorktree, spawnTerminal, toIpcError } from "./tauri";

describe("Tauri IPC wrapper contract", () => {
  beforeEach(() => {
    core.invoke.mockReset();
    core.isTauri.mockReturnValue(true);
  });

  it("spawns terminals with only workspaceId and worktreeId", async () => {
    core.invoke.mockResolvedValue("backend-session-1");

    await expect(spawnTerminal({ workspaceId: "ws-main", worktreeId: "wt-main" })).resolves.toBe("backend-session-1");

    expect(core.invoke).toHaveBeenCalledWith("cmd_terminal_spawn", {
      request: { workspaceId: "ws-main", worktreeId: "wt-main" },
    });
    expect(core.invoke.mock.calls[0][1]).not.toHaveProperty("cwd");
    expect(core.invoke.mock.calls[0][1]).not.toHaveProperty("command");
  });

  it("sends worktree create DTOs in camelCase", async () => {
    core.invoke.mockResolvedValue({ worktreeId: "wt-feature" });

    await createWorktree({ wsId: "ws-main", slug: "feature", baseRef: "HEAD" });

    expect(core.invoke).toHaveBeenCalledWith("cmd_worktree_create", {
      request: { wsId: "ws-main", slug: "feature", baseRef: "HEAD" },
    });
  });

  it("preserves structured errors and does not parse message strings", () => {
    const structured = { code: "DIRTY_WORKTREE", message: "dirty", details: { worktreeId: "wt-main" } };
    expect(toIpcError(structured)).toBe(structured);
    expect(toIpcError("DIRTY_WORKTREE: dirty")).toEqual({
      code: "UNKNOWN",
      message: "Unknown IPC error",
      details: {},
    });
  });
});

import { describe, expect, it } from "vitest";

import type { StructuredIpcError } from "./types";
import { worktreeErrorMessage } from "./ipcErrors";

function error(code: string, message: string): StructuredIpcError {
  return { code, message, details: {} };
}

describe("worktreeErrorMessage", () => {
  it("branches on the structured error code", () => {
    expect(worktreeErrorMessage(error("DIRTY_WORKTREE", "backend wording may change"))).toContain("uncommitted changes");
    expect(worktreeErrorMessage(error("WORKTREE_WRITER_BUSY", "irrelevant"))).toContain("another writer session");
    expect(worktreeErrorMessage(error("INVALID_BASE_REF", "irrelevant"))).toContain("base ref");
  });

  it("never infers an error code by parsing the message", () => {
    expect(worktreeErrorMessage(error("UNKNOWN", "DIRTY_WORKTREE: text only"))).toBe("DIRTY_WORKTREE: text only");
  });
});

import { invoke, isTauri } from "@tauri-apps/api/core";
import { listen, type UnlistenFn } from "@tauri-apps/api/event";

import type {
  StructuredIpcError,
  TerminalLifecyclePayload,
  TerminalOutputPayload,
  Worktree,
  WorktreeChangedPayload,
} from "./types";

export function isTauriRuntime() {
  return isTauri();
}

export async function listWorktrees() {
  if (!isTauri()) return [] as Worktree[];
  return invoke<Worktree[]>("cmd_worktree_list");
}

export async function createWorktree(request: { wsId: string; slug: string; baseRef?: string | null }) {
  return invoke<Worktree>("cmd_worktree_create", {
    request: {
      wsId: request.wsId,
      slug: request.slug,
      baseRef: request.baseRef ?? null,
    },
  });
}

export async function spawnTerminal(request: { workspaceId: string; worktreeId: string }) {
  if (!isTauri()) return `preview:${request.workspaceId}:${request.worktreeId}:${crypto.randomUUID()}`;
  return invoke<string>("cmd_terminal_spawn", { request });
}

export async function writeTerminal(request: { sessionId: string; data: string }) {
  if (!isTauri()) return;
  await invoke("cmd_terminal_write", request);
}

export async function resizeTerminal(request: { sessionId: string; cols: number; rows: number }) {
  if (!isTauri()) return;
  await invoke("cmd_terminal_resize", request);
}

export async function closeTerminal(sessionId: string) {
  if (!isTauri()) return;
  await invoke("cmd_terminal_close", { sessionId });
}

export async function onTerminalOutput(handler: (payload: TerminalOutputPayload) => void): Promise<UnlistenFn> {
  if (!isTauri()) return () => undefined;
  return listen<TerminalOutputPayload>("terminal_output", (event) => handler(event.payload));
}

export async function onTerminalLifecycle(handler: (payload: TerminalLifecyclePayload) => void): Promise<UnlistenFn> {
  if (!isTauri()) return () => undefined;
  return listen<TerminalLifecyclePayload>("terminal_lifecycle", (event) => handler(event.payload));
}

export async function onWorktreeChanged(handler: (payload: WorktreeChangedPayload) => void): Promise<UnlistenFn> {
  if (!isTauri()) return () => undefined;
  return listen<WorktreeChangedPayload>("worktree_changed", (event) => handler(event.payload));
}

export function toIpcError(error: unknown): StructuredIpcError {
  if (isStructuredIpcError(error)) return error;
  return {
    code: "UNKNOWN",
    message: error instanceof Error ? error.message : "Unknown IPC error",
    details: {},
  };
}

export function isStructuredIpcError(error: unknown): error is StructuredIpcError {
  if (!error || typeof error !== "object") return false;
  const candidate = error as Partial<StructuredIpcError>;
  return (
    typeof candidate.code === "string" &&
    typeof candidate.message === "string" &&
    !!candidate.details &&
    typeof candidate.details === "object" &&
    !Array.isArray(candidate.details)
  );
}

